// NewAllStrings creates a new validator that checks if the input string
// is present in the provided list of valid strings.
//
// Since: 2.2
func NewAllStrings(list []string) fyne.StringValidator {
	return func(input string) error {
		for _, allowed := range list {
			if input == allowed {
				return nil
			}
		}
		return errors.New("value not in allowed list")
	}
}
