{"path": "task/workspace/data/validation/all.go", "start": 1, "lines": 22, "offset": 0, "total_lines": 22, "content": "package validation

import "fyne.io/fyne/v2"

// NewAllStrings creates a validator that runs all provided validators in sequence.
// If any validator returns an error, that error is returned immediately.
// If all validators pass, nil is returned.
//
// This allows chaining multiple validators together, for example:
//   validator := validation.NewAllStrings(validation.NewRegexp(`^\d+$`), customValidator)
//
// Since: 2.2
func NewAllStrings(validators ...fyne.StringValidator) fyne.StringValidator {
	return func(input string) error {
		for _, validator := range validators {
			if err := validator(input); err != nil {
				return err
			}
		}
		return nil
	}
}
